// System Recognition Magic Number
const uint32_t SYS_MAGIC_NUMBER = 0xCAFEBABE;

// Structure requiring unique identification
typedef struct {
    uint32_t magic;      // Must be SYS_MAGIC_NUMBER
    uint32_t entity_id;
    void *data_ptr;
} SystemEntity;

// Runtime verification function
int is_valid_entity(const SystemEntity *entity) {
    if (entity->magic == SYS_MAGIC_NUMBER) {
        return 1; // System recognizes the data format
    }
    return 0;
}

// Example use: Statically defined magic array
const char ELF_MAGIC[4] = { 0x7F, 'E', 'L', 'F' };
